def validate_locale(locale: Locale | str) -> Locale:
    if isinstance(locale, str):
        try:
            return Locale(locale)
        except ValueError:
            raise LocaleError(locale)

    if not isinstance(locale, Locale):
        raise LocaleError(locale)

    return locale

def apply_if(
    condition: Callable[[Any], bool],
    transform: Callable[[Any], Any],
    otherwise: Callable[[Any], Any] | None = None,
) -> Callable[[Any], Any]:
    """Apply transform only if the condition is true.

    Example:
        >>> field('word', key=apply_if(lambda x: len(x) > 3, str.upper, str.lower))
        'FIELDS'

    :param condition: Condition function.
    :param transform: Transform function to apply if condition is True.
    :param otherwise: Optional transform to apply if condition is False.
    :return: A closure that conditionally transforms the result.
    """

    def key(v: Any) -> Any:
        if condition(v):
            return transform(v)
        elif otherwise:
            return otherwise(v)
        return v

    return key

def remove_whitespace(value: str) -> str:
    """Remove all whitespace.

    :param value: Input string.
    :return: String with all whitespace removed.
    :raises TypeError: If result is not a string.
    """
    if not isinstance(value, str):
        raise TypeError(
            f"remove_whitespace() requires a string, got {type(value).__name__}"
        )
    return "".join(value.split())

@contextlib.contextmanager
    def override_locale(
        self,
        locale: Locale,
    ) -> t.Generator["BaseDataProvider", None, None]:
        """Context manager that allows overriding current locale.

        Temporarily overrides current locale for
        locale-dependent providers.

        :param locale: Locale.
        :return: Provider with overridden locale.
        """
        try:
            origin_locale = Locale(self.locale)
            self._override_locale(locale)
            try:
                yield self
            finally:
                self._override_locale(origin_locale)
        except AttributeError:
            raise ValueError(f"«{self.__class__.__name__}» has not locale dependent")

